   Precincts & Districts 

   
    html,
    body,
    #viewDiv {
      padding: 0;
      margin: 0;
      height: 100%;
      width: 100%;
    }
   

   
   

   
    require([
      "esri/Map",
      "esri/views/MapView",
	  "esri/layers/FeatureLayer",
      "esri/widgets/Search",
	  "esri/widgets/BasemapToggle",
	  "esri/widgets/ScaleBar",
	  "esri/widgets/LayerList",
      "dojo/domReady!"],
	  
	function( Map, MapView, FeatureLayer, Search, BasemapToggle, ScaleBar, LayerList )
	{
	var map = new Map({
        basemap: "streets"
      });

    var view = new MapView({
        container: "viewDiv",
        map: map,
        center: [-116.711679789558, 46.8161275055622],
        zoom: 10.4
      });
	  
// THIS is the popup Template for the Districts Layer
      var template = { // autocasts as new PopupTemplate()
        title: "Public Service Districts in Latah County, ID",
        content: [{
          type: "fields",
          fieldInfos: [{
            fieldName: "District",
            label: "District:",
            visible: true
          }, {
            fieldName: "Type",
            label: "Type:",
            visible: true,
          }, {
		    fieldName: "Contact",
			label: "For more information, please contact:",
			visible:true,
		  }, {
		    fieldName: "Contact2",
			label: "Contact Number",
			visible: true,	
		  }, {
		    fieldName: "Contact3",
			label: " ",
			visible: true
		  }]		  
        }]
      };
	  
// THIS is the popup Template for Precincts	  
      var template2 = { // autocasts as new PopupTemplate()
        title: "Voter Precincts",
        content: [{
          type: "fields",
          fieldInfos: [{
            fieldName: "Precinct",
            label: "This property is located within Precinct No.:",
            visible: true,
          }, {
		    fieldName: "PollingStation",
			label: "The Polling Station for this Precinct is:",	
		    visible: true, 
		  }, {
			fieldName: "Address",
			label: "and is located at:",
			visible: true,
		  }, {
			fieldName: "Notice",
			label: "NOTICE:",
			visible: true
		  }]
        }]
      };	  
	  
	  
//add FeatureLayers here

	//Parcel Lines
	var Parcels = new FeatureLayer({
        url: "https://gis.latah.id.us/arcgis/rest/services/Parcels1/MapServer/0",
        outFields: ["*"],
		listMode: "hide"
      });
      map.add(Parcels);
	 
	//Section Lines
	var Sections = new FeatureLayer({
		url: "https://gis.latah.id.us/arcgis/rest/services/CadastralData4/MapServer/2",
        outFields: ["*"],
		title: "Sections",
		listMode: "hide"
	  });
	  map.add(Sections);	  

	//Townships & Range Lines
	var Townships = new FeatureLayer({
		url: "https://gis.latah.id.us/arcgis/rest/services/CadastralData4/MapServer/1",
        outFields: ["*"],
		title: "Townships",
		listMode: "hide"
	  });
	  map.add(Townships); 
	  
		//Combined Districts Layer
    var Districts = new FeatureLayer({
        url: "https://gis.latah.id.us/arcgis/rest/services/Districts/MapServer/0",
        outFields: ["*"],
		visible: false,
        popupTemplate: template
      });
      map.add(Districts);
	  
 		//Precincts Layer
    var Precincts = new FeatureLayer({
        url: "https://gis.latah.id.us/arcgis/rest/services/Precincts/MapServer/0",
        outFields: ["*"],
		visible: false,
        popupTemplate: template2
      });
      map.add(Precincts);
	  
	  
//begin adding widgets:
//configure searchWidget	  
      var searchWidget = new Search({
        view: view,
		locationEnabled: false,
        allPlaceholder: "Address Search",
        sources: [
		{
		featureLayer: {
            url: "https://gis.latah.id.us/arcgis/rest/services/Planning_Building2/MapServer/0",
            popupTemplate: { // autocasts as new PopupTemplate()
              title: "<a href={Web_Page} target='_blank'> {Name}</a>, ({Party}-{State}) ",
              overwriteActions: true
            }
          },
          searchFields: ["DLVRY_ADD"],
          displayField: "DLVRY_ADD",
          exactMatch: false,
          outFields: ["*"],
          placeholder: "example: 1214 Kouse",
          name: "Addresses",
          zoomScale: 10000
          ,
        }, 
		{
          featureLayer: {
            url: "https://gis.latah.id.us/arcgis/rest/services/Parcels1/MapServer/0",
            popupTemplate: { // autocasts as new PopupTemplate()
              title: "Parcel:",
              overwriteActions: true
            }
          },
          searchFields: ["PARCEL_ID"],
          displayField: "PARCEL_ID",
          exactMatch: false,
          outFields: ["*"],
          name: "Parcels",
		  zoomScale: 10000,
          placeholder: "example: RP39N03W091492"
        
        }],
		popupEnabled: false
      });
// Add the search widget to the top left corner of the view
        view.ui.add(searchWidget, {
        position: "top-left"
      });
	  
//call Scale Bar	 
		var scaleBar = new ScaleBar({
		view: view
	  });
// Add ScaleBar widget to the bottom left corner of the view
		view.ui.add(scaleBar, {
		position: "bottom-left"
	  });  

//create Basemap Toggle
      var toggle = new BasemapToggle({
      view: view, 
      nextBasemap: "satellite" 
      });
// Add widget to the bottom right corner of the view
      view.ui.add(toggle, "bottom-right");	  
	 
//create layerlist
		var layerList = new LayerList({
		view: view
		});
	// Adds LayerList widget below other elements in the top left corner of the view
		view.ui.add(layerList, {
		position: "top-left"
		});
	 
    });
	
	function notify()
	{
		alert("If you'd like to see Recreation Districts or School Districts as a whole please view Public Map.");
	}
   
 

 
   
